    {
      "title": "While Loop Input Processing Sequence",
      "source_segment_ids": ["FCT_0389", "FCT_0390", "FCT_0391", "FCT_0392", "FCT_0393", "FCT_0394", "FCT_0395", "FCT_0396", "FCT_0397", "FCT_0398"],
      "mode": "visual_only",
