      "visuals": [
        {
          "source_segment_ids": ["FCT_0389", "FCT_0390", "FCT_0395", "FCT_0396", "FCT_0398"],
          "needs_review": false,
          "missing_information": null,
          "evidence": [
            {
              "note_id": "FCT_0389",
              "exact_quote": "A while loop can be used when the number of iterations is not known in advance, such as reading user input until \"quit\" is entered."
            },
            {
              "note_id": "FCT_0390",
              "exact_quote": "One way to solve this problem is to check the input before printing it."
            },
            {
              "note_id": "FCT_0395",
              "exact_quote": "We can reverse this condition: if the user types quit, break out of the loop."
            },
            {
              "note_id": "FCT_0396",
              "exact_quote": "Remove the not operator: if the user types quit, we break."
            },
            {
              "note_id": "FCT_0398",
              "exact_quote": "When Java sees the break statement it will ignore everything else after and terminate the loop."
            }
          ],
          "payload": {
            "type": "sequence",
            "title": "While Loop Reading Input Until Quit",
            "participants": [
              {"id": "p1", "label": "User"},
              {"id": "p2", "label": "Program"}
            ],
            "events": [
              {"kind": "message", "from": "p1", "to": "p2", "text": "Enter input"},
              {"kind": "message", "from": "p2", "to": "p2", "text": "Check if input == \"quit\""},
              {"kind": "branch", "condition": "input == \"quit\"", "events": [
                {"kind": "message", "from": "p2", "to": "p2", "text": "break (terminate loop)"}
              ]},
              {"kind": "branch", "condition": "input != \"quit\"", "events": [
                {"kind": "message", "from": "p2", "to": "p2", "text": "print input"},
                {"kind": "message", "from": "p2", "to": "p2", "text": "loop back to read next input"}
              ]}
            ]
          }
        }
      ]
